import sys
from collections import defaultdict

def main():
    s = sys.stdin.read().strip()
    n = len(s)
    first_letter_counts = defaultdict(int)
    for i in range(n):
        first_letter_counts[s[i]] += 1
    max_first_letter_count = max(first_letter_counts.values())
    unique_shifts = 0
    for i in range(n):
        if s[i] == s[0]:
            shift_unique = True
            for j in range(1, n):
                if s[(i + j) % n] != s[j]:
                    shift_unique = False
                    break
            if shift_unique:
                unique_shifts += 1
    if unique_shifts > 1:
        probability = 0
    else:
        probability = 1 / max_first_letter_count
    print(f"{probability:.15f}")

main()
